// n8n Code node - "Run Once for All Items" mode

const ACCOUNT_NAME = 'visa'; // adjust if you have multiple cards/PDF sources

function emptyToNull(val) {
  return val === '' || val === undefined ? null : val;
}

function parseNumber(value) {
  if (typeof value !== 'string') return NaN;

  const hasComma = value.includes(',');
  const hasDot = value.includes('.');

  let normalized = value;

  if (hasComma && hasDot) {
    // assume dot = thousand separator, comma = decimal
    normalized = value.replace(/\./g, '').replace(',', '.');
  } else if (hasComma) {
    // comma as decimal
    normalized = value.replace(',', '.');
  }

  return parseFloat(normalized);
}

function buildCounterpartyFields(type, knownAccountId, counterpartyName) {
  if (type === 'withdrawal') {
    return {
      // your own asset account (already known from the PDF) is the source
      ...(knownAccountId != null ? { source_id: knownAccountId } : {}),
      destination_name: counterpartyName,
      destination_iban: null,
      destination_bic: null,
    };
  }
  if (type === 'deposit') {
    return {
      source_name: counterpartyName,
      source_iban: null,
      source_bic: null,
      // your own asset account is now the destination
      ...(knownAccountId != null ? { destination_id: knownAccountId } : {}),
    };
  }
  // transfer / unknown type - pass through what we know
  return knownAccountId != null ? { source_id: knownAccountId } : {};
}

const results = [];

for (const item of $json.transactions) {
  const transactions = item.firefly.transactions || [];

  for (const raw of transactions) {
    const type = raw.type; // already normalized upstream: "withdrawal" / "deposit"
    const amount = parseNumber(raw.amount).toFixed(2);
    const date = raw.date;
    const counterpartyName = raw.description || 'Unknown';
    const knownAccountId = raw.source_id;

    const normalized = {
      id: raw.external_id || `${ACCOUNT_NAME}-${date}-${counterpartyName}`,
      account: ACCOUNT_NAME,
      type,
      date,
      amount,
      currency_code: 'EUR', // adjust if this statement covers another currency
      description: raw.description || '',
      category_name: null,

      ...buildCounterpartyFields(type, knownAccountId, counterpartyName),

      external_id: emptyToNull(raw.external_id),
      internal_reference: null,

      payment_date: date,
      book_date: date,

      tags: [],
      notes: null,

      raw,
    };

    results.push(normalized);
  }
}

return {
  fileId: $json.fileId,
  rowCount: results.length,
  data: results
};
